167:   if (!isValidId(id)) { res.status(400).json({ error: 'Invalid dispatch order id' }); return; }
168:   const { admin_remarks } = req.body;
169:   try {
170:     const result = await withTransaction(async (ctx: DbContext) => {
171:       const order = await ctx.findOne('dispatch_orders', { id }, { projection: { _id: 0 } });
172:       if (!order) throw new SyncError('Dispatch order not found', 'ORDER_NOT_FOUND', 404);
173:       if (order.status !== 'PENDING') {
174:         throw new SyncConflictError(`Order is already ${order.status}`, { order_id: order.id, status: order.status });
175:       }
176: 
177:       const batch = await ctx.findOne('batches', { id: order.batch_id }, { projection: { _id: 0 } });
178:       if (!batch) throw new SyncError('Batch not found', 'BATCH_NOT_FOUND', 404);
179:       if (batch.status !== 'DISPATCH_ORDER_RAISED') {
180:         throw new SyncConflictError(`Batch is not awaiting approval. Current status: ${batch.status}`, {
181:           batch_id: order.batch_id,
182:           current_status: batch.status,
183:         });
184:       }
185: 
186:       const orderUpdate = await ctx.updateOne(
187:         'dispatch_orders',
188:         { id, status: 'PENDING' },
189:         { $set: {
190:           status: 'APPROVED',
191:           admin_id: req.user!.role === 'ADMIN' ? req.user!.userId : null,
192:           approved_by_role: req.user!.role,
193:           approved_by_id: req.user!.userId,
194:           admin_remarks: admin_remarks || null,
195:         } }
196:       );
197:       if (orderUpdate.matchedCount !== 1) {
198:         throw new SyncConflictError('Dispatch order was changed by another user', { order_id: id });
199:       }
200: 
201:       const batchUpdate = await ctx.updateOne(
202:         'batches',
203:         { id: order.batch_id, status: 'DISPATCH_ORDER_RAISED' },
204:         { $set: { status: 'DISPATCH_APPROVED' } }
205:       );
206:       if (batchUpdate.matchedCount !== 1) {
207:         throw new SyncConflictError('Batch was changed by another user', { batch_id: order.batch_id });
208:       }
209: 
210:       await ctx.insert('activity_logs', {
211:         user_id: req.user!.userId,
212:         user_name: req.user!.name,
213:         user_role: req.user!.role,
214:         action: 'DISPATCH_APPROVED',
215:         description: `Dispatch order #${id} approved for batch #${order.batch_id}`,
216:       });
217:       return { message: 'Dispatch order approved', status: 'APPROVED' };
218:     });
219:     res.json(result);
220:   } catch (error) {
