320: /**
321:  * Removes dispatched units from the product's stock counter. Stock is clamped
322:  * at zero so a missing production entry can never create a negative balance.
323:  * The update is a single atomic pipeline so concurrent dispatches cannot
324:  * overwrite each other on standalone MongoDB (which has no transactions).
325:  */
326: async function deductProductStock(
327:   ctx: DbContext,
328:   productId: EntityId,
329:   quantity: number
330: ): Promise<number | null> {
331:   if (!isValidId(productId) || !Number.isFinite(quantity) || quantity <= 0) {
332:     return null;
333:   }
334:   const result = await ctx.findOneAndUpdate('products', { id: productId }, [
335:     {
336:       $set: {
337:         quantity: {
338:           $cond: [
339:             { $lt: [{ $subtract: [{ $ifNull: ['$quantity', 0] }, quantity] }, 0] },
340:             0,
341:             { $subtract: [{ $ifNull: ['$quantity', 0] }, quantity] },
342:           ],
343:         },
344:         updated_at: now(),
345:       },
346:     },
347:   ], { returnDocument: 'after' });
348:   return result ? Number((result as Record<string, any>).quantity) : null;
349: }
