432:   deviceUuid: string | null,
433:   input: SyncOperationInput
434: ): Promise<{ entityType: string; entityId: EntityId; data: Record<string, any> }> {
435:   if (!['QC', 'ADMIN'].includes(user.role)) {
436:     throw new SyncError('Only QC or admin users can submit QC results', 'FORBIDDEN', 403);
437:   }
438:   const payload = input.payload;
439:   const result = String(payload.result || '').toUpperCase();
440:   if (!['PASS', 'FAIL'].includes(result)) {
441:     throw new SyncError('result must be PASS or FAIL', 'INVALID_RESULT');
442:   }
443:   const remarks = typeof payload.remarks === 'string' ? payload.remarks.slice(0, 4000) : null;
444:   const images = imageList(payload);
445:   const barcodes = bulkBarcodes(payload);
446:   const batches = await getBatchesForUpdate(ctx, barcodes);
447: 
448:   const invalid = batches.filter((batch) => String(batch.status) !== 'CREATED');
449:   if (invalid.length > 0) {
450:     throw new SyncConflictError('One or more QR codes are no longer waiting for QC', {
451:       invalid_batches: invalid.map((batch) => ({
452:         batch_id: batch.id,
453:         batch_number: batch.batch_number,
454:         barcode_value: batch.barcode_value,
455:         current_status: batch.status,
456:       })),
457:     });
458:   }
459: 
460:   const newStatus = result === 'PASS' ? 'QC_PASSED' : 'QC_FAILED';
461:   const recordIds: EntityId[] = [];
462:   for (const batch of batches) {
463:     const recordId = await ctx.insert('qc_records', {
464:       batch_id: batch.id,
465:       tester_id: user.userId,
466:       result,
467:       remarks,
468:       images: images.length > 0 ? JSON.stringify(images) : null,
469:       group_operation_id: input.operation_id,
470:       client_created_at: toDate(input.client_timestamp),
471:       device_uuid: deviceUuid,
472:     });
473:     recordIds.push(recordId);
474:     const update = await ctx.updateOne('batches', { id: batch.id, status: 'CREATED' }, {
475:       $set: { status: newStatus },
476:     });
477:     if (update.matchedCount !== 1) {
478:       throw new SyncConflictError('A QR code was changed by another user. Refresh and try again.', {
479:         batch_id: batch.id,
480:         current_status: batch.status,
481:       });
482:     }
483:   }
484: 
485:   await logActivity(
486:     ctx,
487:     user,
488:     result === 'PASS' ? 'QC_PASSED_GROUP' : 'QC_FAILED_GROUP',
489:     `QC ${result} applied to ${batches.length} QR code${batches.length === 1 ? '' : 's'}`
490:   );
491: 
492:   return {
493:     entityType: 'qc_group',
494:     entityId: recordIds[0],
495:     data: {
496:       status: newStatus,
497:       count: batches.length,
498:       batch_ids: batches.map((batch) => batch.id),
499:       batch_numbers: batches.map((batch) => batch.batch_number),
500:       qc_record_ids: recordIds,
501:       result,
502:       images,
503:     },
504:   };
505: }
