507: async function applyDispatchOrderRaise(
508:   ctx: DbContext,
509:   user: JwtPayload,
510:   deviceUuid: string | null,
511:   input: SyncOperationInput
512: ): Promise<{ entityType: string; entityId: EntityId; data: Record<string, any> }> {
513:   if (!['DISPATCH', 'ADMIN'].includes(user.role)) {
514:     throw new SyncError('Only dispatch or admin users can raise dispatch orders', 'FORBIDDEN', 403);
515:   }
516:   const clientId = input.payload.client_id as EntityId;
517:   const driverName = String(input.payload.driver_name || '').trim().slice(0, 150);
518:   const vehicleNumber = String(input.payload.vehicle_number || '').trim().slice(0, 50);
519:   const containerNumber = String(input.payload.container_number || '').trim().slice(0, 100);
520:   if (!isValidId(clientId) || !driverName || !vehicleNumber || !containerNumber) {
521:     throw new SyncError('Select a client and provide the driver, vehicle, and container details', 'DISPATCH_DETAILS_REQUIRED');
522:   }
523:   const client = await ctx.findOne('clients', { id: clientId, is_active: 1 }, { projection: { id: 1 } });
524:   if (!client) {
525:     throw new SyncError('Selected client is no longer active', 'CLIENT_NOT_FOUND', 404);
526:   }
527:   const batch = await getBatchForUpdate(ctx, input.payload);
528:   if (input.payload.expected_status && String(input.payload.expected_status) !== String(batch.status)) {
529:     throw new SyncConflictError('Batch status changed while this order was offline', {
530:       batch_id: batch.id,
531:       expected_status: input.payload.expected_status,
532:       current_status: batch.status,
533:     });
534:   }
535:   assertStatus(
536:     batch,
537:     ['QC_PASSED', 'DISPATCH_REJECTED'],
538:     `Dispatch order can only be raised for QC_PASSED or DISPATCH_REJECTED batches. Current status: ${batch.status}`
539:   );
540:   if (!batch.fg_details_completed_at) {
541:     const labelCount = await ctx.count('qr_labels', { batch_id: batch.id });
542:     if (labelCount !== Number(batch.quantity)) {
543:       throw new SyncConflictError('Complete finished-goods details and generate bag QR labels before raising a dispatch order', {
544:         batch_id: batch.id,
545:         expected_qr_count: Number(batch.quantity),
546:         actual_qr_count: labelCount,
547:       });
548:     }
549:   }
550:   if (Number(batch.quantity) > 1) {
551:     const labelCount = await ctx.count('qr_labels', { batch_id: batch.id });
552:     if (labelCount !== Number(batch.quantity)) {
553:       throw new SyncConflictError('Batch unit QR labels are incomplete. Contact an administrator.', {
554:         batch_id: batch.id,
555:         expected_qr_count: Number(batch.quantity),
556:         actual_qr_count: labelCount,
557:       });
558:     }
559:   }
560: 
561:   const existing = await ctx.find('dispatch_orders', {
562:     batch_id: batch.id,
563:     status: { $in: ['PENDING', 'APPROVED'] },
564:   }, { sort: { created_at: -1 }, limit: 1, projection: { _id: 0, id: 1, status: 1 } });
565:   if (existing.length > 0) {
566:     throw new SyncConflictError(
567:       existing[0].status === 'APPROVED'
568:         ? 'This batch already has an approved dispatch order'
569:         : 'A dispatch order is already pending for this batch',
570:       { order_id: existing[0].id, order_status: existing[0].status }
571:     );
572:   }
573: 
574:   const orderId = await ctx.insert('dispatch_orders', {
575:     batch_id: batch.id,
576:     raised_by: user.userId,
577:     status: 'PENDING',
578:     admin_id: null,
579:     admin_remarks: null,
580:     client_id: clientId,
581:     driver_name: driverName,
582:     vehicle_number: vehicleNumber,
583:     container_number: containerNumber,
584:     client_operation_id: input.operation_id,
585:     client_created_at: toDate(input.client_timestamp),
586:     device_uuid: deviceUuid,
587:     dispatched_at: null,
588:   });
589: 
590:   const update = await ctx.updateOne('batches', { id: batch.id, status: batch.status }, {
591:     $set: { status: 'DISPATCH_ORDER_RAISED' },
592:   });
593:   if (update.matchedCount !== 1) {
594:     throw new SyncConflictError('Batch was changed by another user. Refresh and try again.', {
595:       batch_id: batch.id,
596:       current_status: batch.status,
597:     });
598:   }
599: 
600:   await logActivity(
601:     ctx,
602:     user,
603:     'DISPATCH_ORDER_RAISED',
604:     `Dispatch order raised for batch ${batch.batch_number} (${batch.product_name})`
605:   );
606: 
607:   return {
608:     entityType: 'dispatch_order',
609:     entityId: orderId,
610:     data: {
611:       id: orderId,
612:       batch_id: batch.id,
613:       batch_number: batch.batch_number,
614:       product_name: batch.product_name,
615:       status: 'PENDING',
616:     },
617:   };
618: }
