620: async function applyDispatchConfirm(
621:   ctx: DbContext,
622:   user: JwtPayload,
623:   deviceUuid: string | null,
624:   input: SyncOperationInput
625: ): Promise<{ entityType: string; entityId: EntityId; data: Record<string, any> }> {
626:   if (!['DISPATCH', 'ADMIN'].includes(user.role)) {
627:     throw new SyncError('Only dispatch or admin users can confirm dispatches', 'FORBIDDEN', 403);
628:   }
629:   const payload = input.payload;
630:   const remarks = typeof payload.remarks === 'string' ? payload.remarks.slice(0, 4000) : null;
631:   const images = imageList(payload);
632:   const batch = await getBatchForUpdate(ctx, payload);
633:   if (Number(batch.quantity) > 1) {
634:     throw new SyncConflictError('Scan every unit QR code in the batch before completing dispatch', {
635:       batch_id: batch.id,
636:       batch_number: batch.batch_number,
637:       expected_qr_count: Number(batch.quantity),
638:       scanned_qr_count: 1,
639:     });
640:   }
641: 
642:   if (payload.expected_status && String(payload.expected_status) !== String(batch.status)) {
643:     throw new SyncConflictError('Batch status changed while this dispatch was offline', {
644:       batch_id: batch.id,
645:       expected_status: payload.expected_status,
646:       current_status: batch.status,
647:     });
648:   }
649: 
650:   if (batch.status === 'DISPATCHED') {
651:     throw new SyncConflictError('Batch is already dispatched', {
652:       batch_id: batch.id,
653:       current_status: batch.status,
654:     });
655:   }
656:   if (batch.status === 'DISPATCH_ORDER_RAISED') {
657:     throw new SyncConflictError('Dispatch order is still awaiting admin approval', {
658:       batch_id: batch.id,
659:       current_status: batch.status,
660:     });
661:   }
662: 
663:   let orderId: EntityId | null = null;
664:   if (batch.status === 'DISPATCH_APPROVED') {
665:     const orders = await ctx.find('dispatch_orders', {
666:       batch_id: batch.id,
667:       status: 'APPROVED',
668:     }, { sort: { created_at: -1 }, limit: 1, projection: { _id: 0, id: 1 } });
669:     if (orders.length === 0) {
670:       throw new SyncConflictError('No approved dispatch order was found for this batch', {
671:         batch_id: batch.id,
672:         current_status: batch.status,
673:       });
674:     }
675:     orderId = orders[0].id as EntityId;
676:   } else if (batch.status === 'QC_PASSED') {
677:     const directAllowed = payload.direct === true && (user.role === 'ADMIN' || process.env.ALLOW_DIRECT_DISPATCH === 'true');
678:     if (!directAllowed) {
679:       throw new SyncConflictError('Raise a dispatch order and wait for admin approval before dispatching', {
680:         batch_id: batch.id,
681:         current_status: batch.status,
682:       });
683:     }
684:   } else {
685:     throw new SyncConflictError(`Batch cannot be dispatched from status ${batch.status}`, {
686:       batch_id: batch.id,
687:       current_status: batch.status,
688:     });
689:   }
690: 
691:   const dispatchRecordId = await ctx.insert('dispatch_records', {
692:     batch_id: batch.id,
693:     dispatcher_id: user.userId,
694:     remarks,
695:     images: images.length > 0 ? JSON.stringify(images) : null,
696:     dispatch_order_id: orderId,
697:     client_operation_id: input.operation_id,
698:     client_created_at: toDate(input.client_timestamp),
699:     device_uuid: deviceUuid,
700:   });
701: 
702:   const update = await ctx.updateOne('batches', { id: batch.id, status: batch.status }, {
703:     $set: { status: 'DISPATCHED' },
704:   });
705:   if (update.matchedCount !== 1) {
706:     throw new SyncConflictError('Batch was changed by another user. Refresh and try again.', {
707:       batch_id: batch.id,
708:       current_status: batch.status,
709:     });
710:   }
711: 
712:   if (orderId) {
713:     await ctx.updateOne('dispatch_orders', { id: orderId }, { $set: { dispatched_at: now() } });
714:   }
715: 
716:   const dispatchedQuantity = Number(batch.quantity) || 0;
717:   const remainingStock = await deductProductStock(
718:     ctx,
719:     batch.product_id as EntityId,
720:     dispatchedQuantity
721:   );
722: 
723:   await logActivity(
724:     ctx,
725:     user,
726:     'DISPATCHED',
727:     `Batch ${batch.batch_number} (${batch.product_name}) dispatched` +
728:       (remainingStock === null
729:         ? ''
730:         : `. Stock deducted: ${dispatchedQuantity}; ${remainingStock} remaining`)
731:   );
732: 
733:   return {
734:     entityType: 'dispatch_record',
735:     entityId: dispatchRecordId,
736:     data: {
737:       status: 'DISPATCHED',
738:       batch_id: batch.id,
739:       batch_number: batch.batch_number,
740:       dispatch_record_id: dispatchRecordId,
741:       dispatch_order_id: orderId,
742:       images,
743:       product_id: batch.product_id,
744:       dispatched_quantity: dispatchedQuantity,
745:       remaining_stock: remainingStock,
746:     },
747:   };
748: }
