750: async function applyDispatchConfirmBulk(
751:   ctx: DbContext,
752:   user: JwtPayload,
753:   deviceUuid: string | null,
754:   input: SyncOperationInput
755: ): Promise<{ entityType: string; entityId: EntityId; data: Record<string, any> }> {
756:   if (!['DISPATCH', 'ADMIN'].includes(user.role)) {
757:     throw new SyncError('Only dispatch or admin users can confirm dispatches', 'FORBIDDEN', 403);
758:   }
759:   const payload = input.payload;
760:   const remarks = typeof payload.remarks === 'string' ? payload.remarks.slice(0, 4000) : null;
761:   const images = imageList(payload);
762:   const barcodes = bulkBarcodes(payload);
763:   const requestedOrderId = payload.dispatch_order_id as EntityId;
764:   // Web dispatch selects one approved order up front, while the offline mobile
765:   // group scan only knows the approved batches. Enforce the selected order only
766:   // when the client actually sent one; otherwise each batch is dispatched
767:   // against its own approved order below.
768:   const hasRequestedOrderId = requestedOrderId !== undefined &&
769:     requestedOrderId !== null &&
770:     String(requestedOrderId).trim() !== '';
771:   const batches = await getBatchesForUpdate(ctx, barcodes);
772: 
773:   const directAllowed = payload.direct === true &&
774:     (user.role === 'ADMIN' || process.env.ALLOW_DIRECT_DISPATCH === 'true');
775:   const recordIds: EntityId[] = [];
776:   const orderIds: EntityId[] = [];
777:   const stockDeductions: Array<{
778:     batch_id: EntityId;
779:     product_id: EntityId;
780:     quantity: number;
781:     remaining_stock: number | null;
782:   }> = [];
783: 
784:   for (const batch of batches) {
785:     if (batch.status === 'DISPATCHED') {
786:       throw new SyncConflictError('One or more QR codes are already dispatched', {
787:         batch_id: batch.id,
788:         barcode_value: batch.barcode_value,
789:         current_status: batch.status,
790:       });
791:     }
792:     if (batch.status === 'DISPATCH_ORDER_RAISED') {
793:       throw new SyncConflictError('A dispatch order is still awaiting admin approval', {
794:         batch_id: batch.id,
795:         barcode_value: batch.barcode_value,
796:         current_status: batch.status,
797:       });
798:     }
799: 
800:     let orderId: EntityId | null = null;
801:     if (batch.status === 'DISPATCH_APPROVED') {
802:       const orders = await ctx.find('dispatch_orders', {
803:         batch_id: batch.id,
804:         status: 'APPROVED',
805:       }, { sort: { created_at: -1 }, limit: 1, projection: { _id: 0, id: 1 } });
806:       if (orders.length === 0) {
807:         throw new SyncConflictError('No approved dispatch order was found for a scanned QR code', {
808:           batch_id: batch.id,
809:           barcode_value: batch.barcode_value,
810:           current_status: batch.status,
811:         });
812:       }
813:       orderId = orders[0].id as EntityId;
814:       if (hasRequestedOrderId && (!isValidId(requestedOrderId) || idKey(requestedOrderId) !== idKey(orderId))) {
815:         throw new SyncConflictError('Scan bags for one approved dispatch order at a time', {
816:           batch_id: batch.id,
817:           expected_order_id: orderId,
818:           requested_order_id: payload.dispatch_order_id ?? null,
819:         });
820:       }
821:       orderIds.push(orderId);
822:     } else if (batch.status === 'QC_PASSED') {
823:       if (!directAllowed) {
824:         throw new SyncConflictError('Raise dispatch orders and wait for admin approval before dispatching', {
825:           batch_id: batch.id,
826:           barcode_value: batch.barcode_value,
827:           current_status: batch.status,
828:         });
829:       }
830:     } else {
831:       throw new SyncConflictError(`QR code cannot be dispatched from status ${batch.status}`, {
832:         batch_id: batch.id,
833:         barcode_value: batch.barcode_value,
834:         current_status: batch.status,
835:       });
836:     }
837: 
838:     const recordId = await ctx.insert('dispatch_records', {
839:       batch_id: batch.id,
840:       dispatcher_id: user.userId,
841:       remarks,
842:       images: images.length > 0 ? JSON.stringify(images) : null,
843:       dispatch_order_id: orderId,
844:       group_operation_id: input.operation_id,
845:       client_created_at: toDate(input.client_timestamp),
846:       device_uuid: deviceUuid,
847:     });
848:     recordIds.push(recordId);
849: 
850:     const update = await ctx.updateOne('batches', { id: batch.id, status: batch.status }, {
851:       $set: { status: 'DISPATCHED' },
852:     });
853:     if (update.matchedCount !== 1) {
854:       throw new SyncConflictError('A QR code was changed by another user. Refresh and try again.', {
855:         batch_id: batch.id,
856:         current_status: batch.status,
857:       });
858:     }
859:     if (orderId) {
860:       await ctx.updateOne('dispatch_orders', { id: orderId }, { $set: { dispatched_at: now() } });
861:     }
862: 
863:     const dispatchedQuantity = Number(batch.quantity) || 0;
864:     const remainingStock = await deductProductStock(
865:       ctx,
866:       batch.product_id as EntityId,
867:       dispatchedQuantity
868:     );
869:     if (remainingStock !== null) {
870:       stockDeductions.push({
871:         batch_id: batch.id as EntityId,
872:         product_id: batch.product_id as EntityId,
873:         quantity: dispatchedQuantity,
874:         remaining_stock: remainingStock,
875:       });
876:     }
877:   }
878: 
879:   await logActivity(
880:     ctx,
881:     user,
882:     'DISPATCHED_GROUP',
883:     `Dispatch confirmed for ${batches.length} QR code${batches.length === 1 ? '' : 's'}` +
884:       (stockDeductions.length > 0 ? '. Product stock updated' : '')
885:   );
886: 
887:   return {
888:     entityType: 'dispatch_group',
889:     entityId: recordIds[0],
890:     data: {
891:       status: 'DISPATCHED',
892:       count: batches.length,
893:       batch_ids: batches.map((batch) => batch.id),
894:       batch_numbers: batches.map((batch) => batch.batch_number),
895:       dispatch_record_ids: recordIds,
896:       dispatch_order_ids: orderIds,
897:       stock_deductions: stockDeductions,
898:       images,
899:     },
900:   };
901: }
