903: /**
904:  * Applies one offline operation in its own transaction. The unique
905:  * operation_id is the idempotency key; retries return the original outcome.
906:  */
907: export async function applyOperation(
908:   user: JwtPayload,
909:   deviceUuid: string | null,
910:   input: SyncOperationInput
911: ): Promise<SyncOperationResult> {
912:   validateOperation(input);
913: 
914:   try {
915:     return await withTransaction(async (ctx) => {
916:       const existing = await findExistingOperation(ctx, input.operation_id);
917:       if (existing) {
918:         if (existing.user_id !== undefined && existing.user_id !== user.userId) {
919:           return {
920:             operation_id: input.operation_id,
921:             status: 'FAILED',
922:             entity_type: null,
923:             entity_id: null,
924:             error: 'Operation belongs to another user',
925:             error_code: 'OPERATION_OWNER_MISMATCH',
926:           };
927:         }
928:         if (existing.status === 'APPLIED' || existing.status === 'DUPLICATE') {
929:           return existing;
930:         }
931:         // A FAILED or CONFLICT operation never committed any business writes:
932:         // its transaction was rolled back. Allow a manual/retry pass with the
933:         // same idempotency key to re-evaluate the current server state.
934:         await ctx.deleteOne('sync_operations', { operation_id: input.operation_id });
935:       }
936: 
937:       let applied: { entityType: string; entityId: EntityId; data: Record<string, any> };
938:       switch (input.type) {
939:         case 'QC_SUBMIT':
940:           applied = await applyQcSubmit(ctx, user, deviceUuid, input);
941:           break;
942:         case 'QC_SUBMIT_BULK':
943:           applied = await applyQcSubmitBulk(ctx, user, deviceUuid, input);
944:           break;
945:         case 'DISPATCH_ORDER_RAISE':
946:           applied = await applyDispatchOrderRaise(ctx, user, deviceUuid, input);
947:           break;
948:         case 'DISPATCH_CONFIRM':
949:           applied = await applyDispatchConfirm(ctx, user, deviceUuid, input);
950:           break;
951:         case 'DISPATCH_CONFIRM_BULK':
952:           applied = await applyDispatchConfirmBulk(ctx, user, deviceUuid, input);
953:           break;
954:         default:
955:           throw new SyncError(`Unsupported operation type: ${input.type}`, 'INVALID_OPERATION_TYPE');
956:       }
957: 
958:       const result: SyncOperationResult = {
959:         operation_id: input.operation_id,
960:         status: 'APPLIED',
961:         entity_type: applied.entityType,
962:         entity_id: applied.entityId,
963:         data: applied.data,
964:         error: null,
965:         error_code: null,
966:       };
967:       await recordOperation(ctx, user, deviceUuid, input, 'APPLIED', null, null, result);
968:       return result;
969:     });
970:   } catch (error) {
971:     if (isDuplicateKey(error)) {
972:       const existing = await findExistingOperation(await getContext(), input.operation_id);
973:       if (existing) return existing;
974:     }
975: 
976:     const isKnown = error instanceof SyncError;
977:     const status: SyncOperationStatus = isKnown && error.code === 'CONFLICT' ? 'CONFLICT' : 'FAILED';
978:     const result: SyncOperationResult = {
979:       operation_id: input.operation_id,
980:       status,
981:       entity_type: null,
982:       entity_id: null,
983:       error: error instanceof Error ? error.message : 'Unknown sync error',
984:       error_code: isKnown ? error.code : 'INTERNAL_ERROR',
985:     };
986: 
987:     try {
988:       await recordOperation(
989:         await getContext(),
990:         user,
991:         deviceUuid,
992:         input,
993:         status,
994:         result.error_code || null,
995:         result.error || null,
996:         result
997:       );
998:     } catch (recordError) {
999:       console.error('Could not record failed sync operation:', recordError);
1000:     }
1001: 
1002:     if (!isKnown) {
1003:       console.error(`Unexpected sync error for ${input.operation_id}:`, error);
1004:     }
1005:     return result;
1006:   }
1007: }
