29: function generateBatchNumber(sku: string, existingBatches: Batch[]): string {
30:   const today = new Date();
31:   const dateStr = today.toISOString().slice(0, 10).replace(/-/g, '');
32:   const prefix = `${sku}-${dateStr}`;
33:   const lastSequence = existingBatches.reduce((max, batch) => {
34:     const suffix = batch.batch_number.startsWith(`${prefix}-`)
35:       ? batch.batch_number.slice(prefix.length + 1)
36:       : '';
37:     return /^\d+$/.test(suffix) ? Math.max(max, Number(suffix)) : max;
38:   }, 0);
39:   const seq = String(lastSequence + 1).padStart(3, '0');
40:   return `${prefix}-${seq}`;
