100:     cells.forEach((cell) => doc.text(cell.text, cell.x, y));
101:     doc.setDrawColor(225, 231, 238);
102:     doc.line(margin, y + height - 2, pageWidth - margin, y + height - 2);
103:     y += height;
104:   });
105: 
106:   doc.save(filename);
107: }
