602:   }
603: 
604:   const sealNumber = trimmed(req.body?.seal_number);
605:   if (!sealNumber) {
606:     res.status(400).json({ error: 'Seal number is required', code: 'SEAL_NUMBER_REQUIRED' });
607:     return;
608:   }
