613:       code: 'INVALID_OUTCOME',
614:     });
615:     return;
616:   }
617:   const remarks = optionalText(req.body?.remarks);
618:   const clientOperationId = optionalText(req.body?.client_operation_id, 64);
619: 
620:   try {
621:     const result = await withTransaction(async (ctx: DbContext) => {
622:       const session = await ctx.findOne('loading_sessions', { id });
623:       if (!session) throw new SyncError('Loading session not found', 'SESSION_NOT_FOUND', 404);
624:       if (req.user!.role === 'DISPATCH' && idKey(session.loader_id) !== idKey(req.user!.userId)) {
625:         throw new SyncError('You can only finalise your own loading sessions', 'FORBIDDEN', 403);
626:       }
627:       if (String(session.status) !== 'ACTIVE') {
628:         throw new SyncError('This loading session is already closed', 'SESSION_CLOSED', 409, {
629:           session_id: session.id,
