637:       if (!batch) throw new SyncError('Batch not found', 'BATCH_NOT_FOUND', 404);
638: 
639:       const completedAt = now();
640:       const sessionUpdate = await ctx.updateOne(
641:         'loading_sessions',
642:         { id: session.id, status: 'ACTIVE' },
643:         {
644:           $set: {
645:             status: 'CLOSED',
646:             seal_number: sealNumber,
647:             outcome,
648:             remarks,
649:             completed_at: completedAt,
650:           },
651:         }
652:       );
653:       if (sessionUpdate.matchedCount !== 1) {
654:         throw new SyncError('This loading session is already closed', 'SESSION_CLOSED', 409, {
655:           session_id: session.id,
656:         });
657:       }
658: 
659:       const orderStatus = outcome === 'DISPATCHED' ? 'CLOSED_DISPATCHED' : 'CLOSED_NOT_DISPATCHED';
660:       await ctx.updateOne(
661:         'dispatch_orders',
662:         { id: order.id },
663:         {
664:           $set: {
665:             status: orderStatus,
666:             seal_number: sealNumber,
