668:             remarks,
669:           },
670:         }
671:       );
672: 
673:       const batchStatus = outcome === 'DISPATCHED' ? 'DISPATCHED' : 'NOT_DISPATCHED';
674:       await ctx.updateOne('batches', { id: batch.id }, { $set: { status: batchStatus } });
675: 
