691: 
692:       await logActivity(
693:         ctx,
694:         req.user!,
695:         'SEAL_NUMBER_RECORDED',
696:         `Seal number ${sealNumber} recorded for loading session ${session.id} (batch ${batch.batch_number})`
697:       );
698:       await logActivity(
699:         ctx,
700:         req.user!,
701:         outcome,
702:         `Loading session ${session.id} for batch ${batch.batch_number} finalised as ${outcome}. Scanned ${numeric(session.scanned)} of ${numeric(session.total)}`
703:       );
704: 
705:       const scanned = numeric(session.scanned);
706:       const total = numeric(session.total);
