const providedBatchNumber = String(batch_number || '').trim();
const autoGenerated = !providedBatchNumber;
const dateStamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
const baseBatchNumber = providedBatchNumber || `${product.sku}-${dateStamp}`;
// Auto-generated numbers must not treat the date stamp as a sequence suffix.
const autoNumbers = (base: string): string[] => (batchCount === 1
  ? [base]
  : Array.from({ length: batchCount }, (_, index) => `${base}-${String(index + 1).padStart(3, '0')}`));
let batchNumbers = autoGenerated
  ? autoNumbers(baseBatchNumber)
  : buildBatchNumbers(baseBatchNumber, batchCount);

if (autoGenerated) {
  // Creating a second lot for the same product on the same day must not fail:
  // walk a suffix until every generated number is free.
  for (let suffix = 1; ; suffix += 1) {
    const clash = await ctx.findOne(
      'batches',
      { batch_number: { $in: batchNumbers } },
      { projection: { id: 1, batch_number: 1 } }
    );
    if (!clash) break;
    if (suffix > 500) {
      res.status(409).json({ error: 'Could not allocate an unused automatic batch number' });
      return;
    }
    batchNumbers = autoNumbers(`${baseBatchNumber}-${suffix}`);
  }
} else {
  const existing = await ctx.findOne('batches', { batch_number: { $in: batchNumbers } }, { projection: { id: 1, batch_number: 1 } });
  if (existing) { res.status(409).json({ error: `Batch number "${existing.batch_number}" already exists` }); return; }
}
if (batchNumbers.some((number) => number.length > 100)) {
  res.status(400).json({ error: 'Generated batch numbers must not exceed 100 characters' });
  return;
}

