const BASE = 'http://127.0.0.1:3101/api';

function assert(condition, message) {
  if (!condition) throw new Error(`ASSERTION FAILED: ${message}`);
}

async function waitForServer() {
  for (let attempt = 0; attempt < 40; attempt += 1) {
    try {
      const response = await fetch(`${BASE}/health`);
      if (response.ok || response.status === 404) return;
    } catch {
      // not up yet
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error('Server did not start on port 3101');
}

async function request(path, { token, method = 'GET', body } = {}) {
  const headers = {};
  if (token) headers.Authorization = `Bearer ${token}`;
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  const response = await fetch(`${BASE}${path}`, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const contentType = response.headers.get('content-type') || '';
  const payload = contentType.includes('application/json')
    ? await response.json().catch(() => null)
    : Buffer.from(await response.arrayBuffer());
  return { status: response.status, payload, headers: response.headers };
}

async function login(email, password) {
  const result = await request('/auth/login', { method: 'POST', body: { email, password } });
  assert(result.status === 200, `login ${email} -> ${result.status} ${JSON.stringify(result.payload)}`);
  return result.payload.token;
}

(async () => {
  await waitForServer();
  const admin = await login('admin@gmail.com', 'admin@123');
  const qc = await login('qc@gmail.com', 'qc@123');
  const dispatch = await login('dispatch@gmail.com', 'dispatch@123');
  console.log('PASS login all roles');

  // Admin masters
  const sku = `SMK-${Date.now()}`;
  const product = await request('/products', {
    token: admin,
    method: 'POST',
    body: { name: 'Smoke Product', sku, price: 10, quantity: 500, grade: 'Technical' },
  });
  assert(product.status === 201, `product create -> ${product.status} ${JSON.stringify(product.payload)}`);
  const productId = product.payload.id ?? product.payload.product?.id;
  assert(productId, 'product id returned');

  const client = await request('/clients', {
    token: admin,
    method: 'POST',
    body: {
      name: 'Smoke Client',
      contact_person: 'Smoke Contact',
      email: 'smoke@example.com',
      phone: '9999999999',
      address: 'Smoke Street',
      gst_number: 'SMOKEGST',
    },
  });
  assert(client.status === 201 || client.status === 200, `client create -> ${client.status} ${JSON.stringify(client.payload)}`);
  const clientId = client.payload.id ?? client.payload.client?.id;
  assert(clientId, 'client id returned');
  console.log('PASS admin masters');

  // QC creates auto-passed batch with 100 unit labels
  const batch = await request('/batches', {
    token: qc,
    method: 'POST',
    body: { product_id: productId, quantity: 100, batch_count: 1 },
  });
  assert(batch.status === 201, `batch create -> ${batch.status} ${JSON.stringify(batch.payload)}`);
  const created = batch.payload.batches[0];
  assert(created.qc_record_id, 'qc_record_id returned');
  assert(created.labels.length === 100, `100 labels generated, got ${created.labels.length}`);
  const batchId = created.id;
  const batchNumber = created.batch_number;

  const batches = await request('/batches', { token: qc });
  const stored = batches.payload.find((row) => row.id === batchId);
  assert(stored?.status === 'QC_PASSED', `batch is QC_PASSED, got ${stored?.status}`);

  const qcRecords = await request('/qc/records?limit=5', { token: qc });
  const recordList = qcRecords.payload.items || qcRecords.payload;
  assert(
    recordList.some((record) => record.batch_id === batchId && record.result === 'PASS' && record.method === 'AUTO_PASS'),
    'auto-pass QC record exists'
  );

  const retired = await request('/qc', { token: qc, method: 'POST', body: { batch_id: batchId, result: 'PASS' } });
  assert(retired.status === 410, `manual QC retired -> 410, got ${retired.status}`);
  console.log('PASS batch auto-pass + retired QC submit');

  // Dispatch raises order
  const raise = await request('/dispatch-orders', {
    token: dispatch,
    method: 'POST',
    body: {
      batch_id: batchId,
      client_id: clientId,
      driver_name: 'Smoke Driver',
      vehicle_number: 'KA01AB1234',
      container_number: 'CONT-1',
      client_operation_id: `raise-${Date.now()}`,
    },
  });
  assert(raise.status === 201, `raise -> ${raise.status} ${JSON.stringify(raise.payload)}`);
  const orderId = raise.payload.order_id ?? raise.payload.order?.id ?? raise.payload.id;
  assert(orderId, `order id returned: ${JSON.stringify(raise.payload)}`);

  const pending = await request('/dispatch-orders/pending', { token: qc });
  assert(pending.payload.some((order) => order.id === orderId), 'order in QC pending queue');

  const adminApprove = await request(`/dispatch-orders/${orderId}/approve`, {
    token: admin,
    method: 'POST',
    body: { remarks: 'admin should not approve' },
  });
  assert(adminApprove.status === 403, `ADMIN approve -> 403, got ${adminApprove.status}`);
  console.log('PASS dispatch raise + QC-only approval guard');

  // QC approves
  const approve = await request(`/dispatch-orders/${orderId}/approve`, {
    token: qc,
    method: 'POST',
    body: { remarks: 'QC approved smoke order' },
  });
  assert(approve.status === 200, `qc approve -> ${approve.status} ${JSON.stringify(approve.payload)}`);

  const approvedOrder = (await request('/dispatch-orders/all', { token: admin })).payload
    .find((order) => order.id === orderId);
  assert(approvedOrder.status === 'APPROVED', `order APPROVED, got ${approvedOrder.status}`);
  assert(approvedOrder.batch_status === 'DISPATCH_APPROVED', `batch DISPATCH_APPROVED, got ${approvedOrder.batch_status}`);
  assert(approvedOrder.approver_name, 'approver name enriched');

  // Packing list JSON + PDF immediately after approval
  const packing = await request(`/dispatch-orders/${orderId}/packing-list`, { token: dispatch });
  assert(packing.status === 200, `packing list -> ${packing.status}`);
  assert(packing.payload.items?.length === 1, 'one frozen packing line');
  assert(packing.payload.items[0].batch_number === batchNumber, 'frozen batch number matches');
  assert(packing.payload.client?.name === 'Smoke Client', 'client snapshot present');

  const pdf = await request(`/dispatch-orders/${orderId}/packing-list.pdf`, { token: dispatch });
  assert(pdf.status === 200, `packing pdf -> ${pdf.status}`);
  assert(pdf.headers.get('content-type')?.includes('application/pdf'), 'pdf content-type');
  assert(pdf.payload.subarray(0, 5).toString() === '%PDF-', 'pdf magic header');
  console.log('PASS approval freeze + JSON/PDF download');

  // Start loading session
  const start = await request('/loading-sessions', {
    token: dispatch,
    method: 'POST',
    body: { dispatch_order_id: orderId, client_operation_id: `start-${Date.now()}` },
  });
  assert(start.status === 201, `start session -> ${start.status} ${JSON.stringify(start.payload)}`);
  const sessionId = start.payload.session.id;
  assert(start.payload.session.total === 100, `session total 100, got ${start.payload.session.total}`);

  const orders = await request('/dispatch-orders/mine?status=APPROVED', { token: dispatch });
  assert(!orders.payload.some((order) => order.id === orderId), 'started order leaves APPROVED list');

  // Scan 10 distinct labels
  for (let index = 0; index < 10; index += 1) {
    const scan = await request(`/loading-sessions/${sessionId}/scan`, {
      token: dispatch,
      method: 'POST',
      body: { qr_value: created.labels[index].qr_value, client_operation_id: `scan-${index}-${Date.now()}` },
    });
    assert(scan.status === 200, `scan ${index} -> ${scan.status} ${JSON.stringify(scan.payload)}`);
    assert(scan.payload.result === 'OK', `scan ${index} OK, got ${scan.payload.result}`);
    assert(scan.payload.scanned === index + 1, `scanned=${index + 1}, got ${scan.payload.scanned}`);
  }

  const duplicate = await request(`/loading-sessions/${sessionId}/scan`, {
    token: dispatch,
    method: 'POST',
    body: { qr_value: created.labels[0].qr_value, client_operation_id: `dup-${Date.now()}` },
  });
  assert(duplicate.payload.result === 'DUPLICATE', `duplicate -> DUPLICATE, got ${duplicate.payload.result}`);
  assert(duplicate.payload.scanned === 10, `duplicate keeps scanned=10, got ${duplicate.payload.scanned}`);

  const wrong = await request(`/loading-sessions/${sessionId}/scan`, {
    token: dispatch,
    method: 'POST',
    body: { qr_value: 'QR:does-not-exist', client_operation_id: `wrong-${Date.now()}` },
  });
  assert(wrong.payload.result === 'WRONG_BATCH', `foreign -> WRONG_BATCH, got ${wrong.payload.result}`);
  assert(wrong.payload.scanned === 10, `wrong batch keeps scanned=10, got ${wrong.payload.scanned}`);

  const detail = await request(`/loading-sessions/${sessionId}`, { token: dispatch });
  assert(detail.payload.session.scanned === 10 && detail.payload.session.total === 100, '10/100 session');
  assert(detail.payload.events.length >= 10, 'scan events recorded');
  console.log('PASS scanning OK / DUPLICATE / WRONG_BATCH');

  // Admin live preview
  const active = await request('/loading-sessions/active', { token: admin });
  const live = active.payload.find((row) => row.session_id === sessionId || row.id === sessionId);
  assert(live, 'active session visible to admin');
  assert(live.scanned === 10 && live.total === 100, `admin sees 10/100, got ${live.scanned}/${live.total}`);
  assert(live.progress === 10, `progress 10, got ${live.progress}`);
  assert(live.last_event, 'last event present');
  console.log('PASS admin live preview 10/100');

  // Finalise validation + success
  const noSeal = await request(`/loading-sessions/${sessionId}/finalise`, {
    token: dispatch,
    method: 'POST',
    body: { seal_number: '   ', outcome: 'DISPATCHED' },
  });
  assert(noSeal.status === 400, `empty seal -> 400, got ${noSeal.status}`);

  const finalise = await request(`/loading-sessions/${sessionId}/finalise`, {
    token: dispatch,
    method: 'POST',
    body: {
      seal_number: 'SEAL-SMOKE-1',
      outcome: 'DISPATCHED',
      remarks: 'Smoke test shortfall 10/100',
      client_operation_id: `final-${Date.now()}`,
    },
  });
  assert(finalise.status === 200, `finalise -> ${finalise.status} ${JSON.stringify(finalise.payload)}`);
  assert(finalise.payload.order_status === 'CLOSED_DISPATCHED', `order closed dispatched, got ${finalise.payload.order_status}`);
  assert(finalise.payload.batch_status === 'DISPATCHED', `batch dispatched, got ${finalise.payload.batch_status}`);

  const closedSession = await request(`/loading-sessions/${sessionId}`, { token: admin });
  assert(closedSession.payload.session.seal_number === 'SEAL-SMOKE-1', 'seal stored on session');
  assert(closedSession.payload.session.outcome === 'DISPATCHED', 'outcome stored on session');

  const rescan = await request(`/loading-sessions/${sessionId}/scan`, {
    token: dispatch,
    method: 'POST',
    body: { qr_value: created.labels[10].qr_value, client_operation_id: `post-${Date.now()}` },
  });
  assert(rescan.status === 409, `scan after close -> 409, got ${rescan.status}`);

  const closedPacking = await request(`/dispatch-orders/${orderId}/packing-list`, { token: dispatch });
  assert(closedPacking.payload.seal_number === 'SEAL-SMOKE-1', 'seal on packing list');
  assert(closedPacking.payload.outcome === 'DISPATCHED', 'outcome on packing list');
  console.log('PASS seal + finalise DISPATCHED');

  // Batch + report state
  const finalBatch = (await request('/batches', { token: admin })).payload.find((row) => row.id === batchId);
  assert(finalBatch.status === 'DISPATCHED', `batch final status, got ${finalBatch.status}`);

