const BASE = 'http://127.0.0.1:3101/api';

function assert(condition, message) {
  if (!condition) throw new Error(`ASSERTION FAILED: ${message}`);
}

async function request(path, { token, method = 'GET', body } = {}) {
  const headers = {};
  if (token) headers.Authorization = `Bearer ${token}`;
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  const response = await fetch(`${BASE}${path}`, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const contentType = response.headers.get('content-type') || '';
  const payload = contentType.includes('application/json')
    ? await response.json().catch(() => null)
    : Buffer.from(await response.arrayBuffer());
  return { status: response.status, payload, headers: response.headers };
}

async function login(email, password) {
  const result = await request('/auth/login', { method: 'POST', body: { email, password } });
  assert(result.status === 200, `login ${email} -> ${result.status}`);
  return result.payload.token;
}

(async () => {
  const admin = await login('admin@gmail.com', 'admin@123');
  const qc = await login('qc@gmail.com', 'qc@123');
  const dispatch = await login('dispatch@gmail.com', 'dispatch@123');

  const sku = `SMK2-${Date.now()}`;
  const product = await request('/products', {
    token: admin,
    method: 'POST',
    body: { name: 'Smoke Product 2', sku, price: 25, quantity: 100 },
  });
  assert(product.status === 201, `product create -> ${product.status}`);
  const productId = product.payload.id ?? product.payload.product?.id;

  const client = await request('/clients', {
    token: admin,
    method: 'POST',
    body: { name: 'Smoke Client 2', email: 'smoke2@example.com', phone: '8888888888' },
  });
  assert(client.status === 201 || client.status === 200, `client create -> ${client.status}`);
  const clientId = client.payload.id ?? client.payload.client?.id;

  // Auto batch numbers must not collide for the same product on the same day.
  const first = await request('/batches', {
    token: qc,
    method: 'POST',
    body: { product_id: productId, quantity: 2, batch_count: 1 },
  });
  const second = await request('/batches', {
    token: qc,
    method: 'POST',
    body: { product_id: productId, quantity: 2, batch_count: 1 },
  });
  assert(first.status === 201 && second.status === 201, `two auto batches -> ${first.status}/${second.status}`);
  const batchA = first.payload.batches[0];
  const batchB = second.payload.batches[0];
  assert(batchA.batch_number !== batchB.batch_number, 'auto batch numbers are unique');
  assert(batchA.batch_number.length <= 100, 'auto batch number length ok');
  console.log(`PASS auto batch numbers: ${batchA.batch_number} / ${batchB.batch_number}`);

  // Reject requires remarks and must reset batch state.
  const raiseA = await request('/dispatch-orders', {
    token: dispatch,
    method: 'POST',
    body: {
      batch_id: batchA.id,
      client_id: clientId,
      driver_name: 'Driver A',
      vehicle_number: 'KA02CD5678',
      container_number: 'CONT-A',
      client_operation_id: `raise-a-${Date.now()}`,
    },
  });
  assert(raiseA.status === 201, `raise A -> ${raiseA.status}`);
  const orderA = raiseA.payload.order_id ?? raiseA.payload.order?.id ?? raiseA.payload.id;

  const badReject = await request(`/dispatch-orders/${orderA}/reject`, {
    token: qc,
    method: 'POST',
    body: { remarks: '   ' },
  });
  assert(badReject.status === 400, `blank reject remarks -> 400, got ${badReject.status}`);

  const reject = await request(`/dispatch-orders/${orderA}/reject`, {
    token: qc,
    method: 'POST',
    body: { remarks: 'Documents missing' },
  });
  assert(reject.status === 200, `reject -> ${reject.status}`);
  const rejectedBatch = (await request('/batches', { token: qc })).payload.find((row) => row.id === batchA.id);
  assert(rejectedBatch.status === 'QC_PASSED', `rejected batch back to QC_PASSED, got ${rejectedBatch.status}`);

  const raiseAgain = await request('/dispatch-orders', {
    token: dispatch,
    method: 'POST',
    body: {
      batch_id: batchA.id,
      client_id: clientId,
      driver_name: 'Driver A',
      vehicle_number: 'KA02CD5678',
      container_number: 'CONT-A2',
      client_operation_id: `raise-a2-${Date.now()}`,
    },
  });
  assert(raiseAgain.status === 201, `re-raise after rejection -> ${raiseAgain.status}`);
  const orderA2 = raiseAgain.payload.order_id ?? raiseAgain.payload.order?.id ?? raiseAgain.payload.id;
  const approve = await request(`/dispatch-orders/${orderA2}/approve`, {
    token: qc,
    method: 'POST',
    body: { remarks: 'Corrected' },
  });
  assert(approve.status === 200, `approve re-raised -> ${approve.status}`);
  console.log('PASS QC rejection cycle + required remarks');

  // NOT_DISPATCHED finalise path.
  const start = await request('/loading-sessions', {
    token: dispatch,
    method: 'POST',
    body: { dispatch_order_id: orderA2 },
  });
  assert(start.status === 201, `start -> ${start.status}`);
  const sessionId = start.payload.session.id;

  const scanOp = `scan-op-${Date.now()}`;
  const scanOne = await request(`/loading-sessions/${sessionId}/scan`, {
    token: dispatch,
    method: 'POST',
    body: { qr_value: batchA.labels[0].qr_value, client_operation_id: scanOp },
  });
  assert(scanOne.status === 200 && scanOne.payload.scanned === 1, 'first scan ok');

  const replay = await request(`/loading-sessions/${sessionId}/scan`, {
    token: dispatch,
    method: 'POST',
    body: { qr_value: batchA.labels[0].qr_value, client_operation_id: scanOp },
  });
  assert(replay.payload.duplicate === true, 'replayed client_operation_id is duplicate');
  assert(replay.payload.scanned === 1, `replay does not increment, got ${replay.payload.scanned}`);

  const secondScan = await request(`/loading-sessions/${sessionId}/scan`, {
    token: dispatch,
    method: 'POST',
    body: { qr_value: batchA.labels[1].qr_value, client_operation_id: `scan2-${Date.now()}` },
  });
  assert(secondScan.payload.scanned === 2, `second distinct scan -> 2, got ${secondScan.payload.scanned}`);

  const finalise = await request(`/loading-sessions/${sessionId}/finalise`, {
    token: dispatch,
    method: 'POST',
    body: { seal_number: 'SEAL-SMOKE-2', outcome: 'NOT_DISPATCHED', remarks: 'Truck rejected' },
  });
  assert(finalise.status === 200, `finalise not dispatched -> ${finalise.status}`);
  assert(finalise.payload.order_status === 'CLOSED_NOT_DISPATCHED', `order closed not dispatched, got ${finalise.payload.order_status}`);
  assert(finalise.payload.batch_status === 'NOT_DISPATCHED', `batch not dispatched, got ${finalise.payload.batch_status}`);

  const finalBatch = (await request('/batches', { token: admin })).payload.find((row) => row.id === batchA.id);
  assert(finalBatch.status === 'NOT_DISPATCHED', `batch status NOT_DISPATCHED, got ${finalBatch.status}`);

  const productAfter = await request(`/products/${productId}`, { token: admin });
  assert(Number(productAfter.payload.quantity) === 100, `stock unchanged on NOT_DISPATCHED, got ${productAfter.payload.quantity}`);

  const report = (await request('/reports/dispatch', { token: admin })).payload
    .find((row) => row.dispatch_order_id === orderA2);
  assert(report.dispatched === 0 && report.outcome === 'NOT_DISPATCHED', 'report dispatched=0');

  const recordCheck = await request(`/dispatch-orders/${orderA2}/packing-list.pdf`, { token: admin });
  assert(recordCheck.status === 200 && recordCheck.payload.subarray(0, 5).toString() === '%PDF-', 'closed order PDF');

  console.log('PASS NOT_DISPATCHED finalise + stock unchanged');
  console.log('\nSMOKE TEST 2 PASSED');
})().catch((error) => {
  console.error('\nSMOKE TEST 2 FAILED');
  console.error(error);
  process.exitCode = 1;
});

