const BASE = 'http://127.0.0.1:3101/api';

function assert(condition, message) {
  if (!condition) throw new Error(`ASSERTION FAILED: ${message}`);
}

async function request(path, { token, method = 'GET', body } = {}) {
  const headers = {};
  if (token) headers.Authorization = `Bearer ${token}`;
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  const response = await fetch(`${BASE}${path}`, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const contentType = response.headers.get('content-type') || '';
  const payload = contentType.includes('application/json')
    ? await response.json().catch(() => null)
    : Buffer.from(await response.arrayBuffer());
  return { status: response.status, payload, headers: response.headers };
}

async function login(email, password) {
  const result = await request('/auth/login', { method: 'POST', body: { email, password } });
  assert(result.status === 200, `login ${email} -> ${result.status}`);
  return result.payload.token;
}

(async () => {
  const admin = await login('admin@gmail.com', 'admin@123');
  const qc = await login('qc@gmail.com', 'qc@123');
  const dispatch = await login('dispatch@gmail.com', 'dispatch@123');

  // Legacy direct-dispatch endpoints are retired.
  const direct = await request('/dispatch', {
    token: dispatch,
    method: 'POST',
    body: { barcode_value: 'QR:anything' },
  });
  assert(direct.status === 410, `/dispatch retired -> 410, got ${direct.status}`);

  const directBulk = await request('/dispatch/bulk', {
    token: dispatch,
    method: 'POST',
    body: { barcodes: ['QR:anything'] },
  });
  assert(directBulk.status === 410, `/dispatch/bulk retired -> 410, got ${directBulk.status}`);

  // Build a fresh product/batch/order and leave it in an ACTIVE session.
  const sku = `SMK3-${Date.now()}`;
  const product = await request('/products', {
    token: admin,
    method: 'POST',
    body: { name: 'Smoke Product 3', sku, price: 5, quantity: 10 },
  });
  assert(product.status === 201, `product -> ${product.status}`);
  const productId = product.payload.id ?? product.payload.product?.id;

  const client = await request('/clients', {
    token: admin,
    method: 'POST',
    body: { name: 'Smoke Client 3', email: 'smoke3@example.com', phone: '7777777777' },
  });
  assert(client.status === 201 || client.status === 200, `client -> ${client.status}`);
  const clientId = client.payload.id ?? client.payload.client?.id;

  const batch = await request('/batches', {
    token: qc,
    method: 'POST',
    body: { product_id: productId, quantity: 3, batch_count: 1 },
  });
  assert(batch.status === 201, `batch -> ${batch.status}`);
  const created = batch.payload.batches[0];

  const raise = await request('/dispatch-orders', {
    token: dispatch,
    method: 'POST',
    body: {
      batch_id: created.id,
      client_id: clientId,
      driver_name: 'Driver C',
      vehicle_number: 'KA03EF9012',
      container_number: 'CONT-C',
      client_operation_id: `raise-c-${Date.now()}`,
    },
  });
  assert(raise.status === 201, `raise -> ${raise.status}`);
  const orderId = raise.payload.order_id ?? raise.payload.order?.id ?? raise.payload.id;

  const approve = await request(`/dispatch-orders/${orderId}/approve`, {
    token: qc,
    method: 'POST',
    body: { remarks: 'ok' },
  });
  assert(approve.status === 200, `approve -> ${approve.status}`);

  const start = await request('/loading-sessions', {
    token: dispatch,
    method: 'POST',
    body: { dispatch_order_id: orderId },
  });
  assert(start.status === 201, `start -> ${start.status}`);
  const sessionId = start.payload.session.id;

  // A dispatcher can list their own active session (needed to resume after reload).
  const ownActive = await request('/loading-sessions/active', { token: dispatch });
  assert(ownActive.status === 200, `dispatch active -> ${ownActive.status}`);
  assert(
    ownActive.payload.some((row) => row.session_id === sessionId || row.id === sessionId),
    'dispatch sees own active session'
  );

  // QC/Admin still see all active sessions.
  for (const [label, token] of [['admin', admin], ['qc', qc]]) {
    const allActive = await request('/loading-sessions/active', { token });
    assert(allActive.status === 200, `${label} active -> ${allActive.status}`);
    assert(
      allActive.payload.some((row) => row.session_id === sessionId || row.id === sessionId),
      `${label} sees active session`
    );
  }

  // Scanning after a duplicate start returns SESSION_EXISTS, which the UI turns into a resume.
  const duplicateStart = await request('/loading-sessions', {
    token: dispatch,
    method: 'POST',
    body: { dispatch_order_id: orderId },
  });
  assert(duplicateStart.status === 409, `duplicate start -> 409, got ${duplicateStart.status}`);
  assert(duplicateStart.payload.code === 'SESSION_EXISTS', 'duplicate start code SESSION_EXISTS');

  console.log('SMOKE TEST 3 PASSED');
})().catch((error) => {
  console.error('SMOKE TEST 3 FAILED');
  console.error(error);
  process.exitCode = 1;
});

